BEGIN;
CREATE TABLE IF NOT EXISTS whatsapp_incidentes_tecnicos (id BIGSERIAL PRIMARY KEY,tipo VARCHAR(50) NOT NULL,severidad VARCHAR(10) NOT NULL,estado VARCHAR(20) NOT NULL DEFAULT 'NUEVO',entidad_tipo VARCHAR(30) NOT NULL,entidad_id BIGINT,recordatorio_id BIGINT REFERENCES whatsapp_recordatorios_cita(id) ON UPDATE CASCADE ON DELETE RESTRICT,respuesta_recepcion_id BIGINT REFERENCES whatsapp_respuestas_recepcion(id) ON UPDATE CASCADE ON DELETE RESTRICT,derivacion_id BIGINT REFERENCES whatsapp_derivaciones_recepcion(id) ON UPDATE CASCADE ON DELETE RESTRICT,evento_id BIGINT REFERENCES whatsapp_eventos(id) ON UPDATE CASCADE ON DELETE RESTRICT,entidad_ref_hash CHAR(64),codigo_error VARCHAR(100),resumen_error VARCHAR(500) NOT NULL,categoria_error VARCHAR(20),recuperable BOOLEAN NOT NULL DEFAULT FALSE,intentos INTEGER NOT NULL DEFAULT 0,proximo_reintento_en TIMESTAMPTZ,ocurrencias INTEGER NOT NULL DEFAULT 1,ultima_ocurrencia_en TIMESTAMPTZ NOT NULL DEFAULT NOW(),revisado_por_usuario_id INTEGER REFERENCES usuarios(id) ON UPDATE CASCADE ON DELETE RESTRICT,revisado_en TIMESTAMPTZ,recuperado_en TIMESTAMPTZ,cancelado_por_usuario_id INTEGER REFERENCES usuarios(id) ON UPDATE CASCADE ON DELETE RESTRICT,cancelado_en TIMESTAMPTZ,resolucion VARCHAR(500),historial JSONB NOT NULL DEFAULT '[]'::jsonb,idempotency_key VARCHAR(255) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CONSTRAINT whatsapp_incidentes_tipo_check CHECK(tipo IN('WEBHOOK_FIRMA_INVALIDA','WEBHOOK_DUPLICADO','CALLBACK_DESCONOCIDO','RECORDATORIO_FALLIDO','RESPUESTA_MANUAL_FALLIDA','META_ERROR')),CONSTRAINT whatsapp_incidentes_severidad_check CHECK(severidad IN('INFO','WARNING','ERROR','CRITICAL')),CONSTRAINT whatsapp_incidentes_estado_check CHECK(estado IN('NUEVO','REVISADO','EN_RECUPERACION','RECUPERADO','CANCELADO')),CONSTRAINT whatsapp_incidentes_entidad_check CHECK(entidad_tipo IN('WEBHOOK','EVENTO','RECORDATORIO','RESPUESTA_RECEPCION')),CONSTRAINT whatsapp_incidentes_categoria_check CHECK(categoria_error IS NULL OR categoria_error IN('TRANSITORIO','PERMANENTE','DESCONOCIDO')),CONSTRAINT whatsapp_incidentes_contadores_check CHECK(intentos>=0 AND ocurrencias>=1),CONSTRAINT whatsapp_incidentes_hash_check CHECK(entidad_ref_hash IS NULL OR entidad_ref_hash ~ '^[a-f0-9]{64}$'),CONSTRAINT whatsapp_incidentes_historial_check CHECK(jsonb_typeof(historial)='array'),CONSTRAINT whatsapp_incidentes_revision_check CHECK((revisado_en IS NULL AND revisado_por_usuario_id IS NULL) OR (revisado_en IS NOT NULL AND revisado_por_usuario_id IS NOT NULL)),CONSTRAINT whatsapp_incidentes_cancelacion_check CHECK((cancelado_en IS NULL AND cancelado_por_usuario_id IS NULL) OR (cancelado_en IS NOT NULL AND cancelado_por_usuario_id IS NOT NULL)),CONSTRAINT whatsapp_incidentes_idempotency_unique UNIQUE(idempotency_key));
CREATE INDEX IF NOT EXISTS whatsapp_incidentes_estado_severidad_fecha_idx ON whatsapp_incidentes_tecnicos(estado,severidad,created_at DESC); CREATE INDEX IF NOT EXISTS whatsapp_incidentes_tipo_fecha_idx ON whatsapp_incidentes_tecnicos(tipo,created_at DESC); CREATE INDEX IF NOT EXISTS whatsapp_incidentes_entidad_idx ON whatsapp_incidentes_tecnicos(entidad_tipo,entidad_id); CREATE INDEX IF NOT EXISTS whatsapp_incidentes_recuperables_idx ON whatsapp_incidentes_tecnicos(proximo_reintento_en) WHERE recuperable=TRUE AND estado IN('NUEVO','REVISADO','EN_RECUPERACION'); CREATE INDEX IF NOT EXISTS whatsapp_incidentes_recordatorio_idx ON whatsapp_incidentes_tecnicos(recordatorio_id) WHERE recordatorio_id IS NOT NULL; CREATE INDEX IF NOT EXISTS whatsapp_incidentes_respuesta_idx ON whatsapp_incidentes_tecnicos(respuesta_recepcion_id) WHERE respuesta_recepcion_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS whatsapp_ejecuciones_jobs(id BIGSERIAL PRIMARY KEY,job_name VARCHAR(50) NOT NULL,started_at TIMESTAMPTZ NOT NULL,finished_at TIMESTAMPTZ,status VARCHAR(20) NOT NULL,processed_count INTEGER NOT NULL DEFAULT 0,success_count INTEGER NOT NULL DEFAULT 0,failure_count INTEGER NOT NULL DEFAULT 0,duration_ms INTEGER,error_summary VARCHAR(500),instance_id_hash CHAR(64),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CONSTRAINT whatsapp_jobs_name_check CHECK(job_name IN('RECORDATORIOS_CITA','ALERTAS_DERIVACIONES')),CONSTRAINT whatsapp_jobs_status_check CHECK(status IN('EJECUTANDO','EXITOSO','FALLIDO','OMITIDO','DESHABILITADO')),CONSTRAINT whatsapp_jobs_contadores_check CHECK(processed_count>=0 AND success_count>=0 AND failure_count>=0 AND(duration_ms IS NULL OR duration_ms>=0)),CONSTRAINT whatsapp_jobs_instance_hash_check CHECK(instance_id_hash IS NULL OR instance_id_hash ~ '^[a-f0-9]{64}$'));
CREATE INDEX IF NOT EXISTS whatsapp_jobs_nombre_inicio_idx ON whatsapp_ejecuciones_jobs(job_name,started_at DESC); CREATE INDEX IF NOT EXISTS whatsapp_jobs_estado_inicio_idx ON whatsapp_ejecuciones_jobs(status,started_at DESC); COMMIT;
